import psycopg
from pgvector.psycopg import register_vector

conn = psycopg.connect("{{dsn}}", autocommit=True)
register_vector(conn)

def insert(content: str, vec):
    conn.execute("INSERT INTO {{table_name}} (content, embedding) VALUES (%s, %s)", (content, vec))

def search(vec, k=5):
    cur = conn.execute(
        "SELECT id, content FROM {{table_name}} ORDER BY embedding <=> %s LIMIT %s",
        (vec, k),
    )
    return cur.fetchall()
